# fix-runner-cleanup.ps1
Set-StrictMode -Off
$ErrorActionPreference = 'Stop'

if (-not (Test-Path 'Create_Package.test.js')) {
    Write-Host 'ERROR: Run from Commercial Line Performance test folder' -ForegroundColor Red; exit 1
}

Write-Host 'Updating runners/run-states.ps1...' -ForegroundColor Yellow
if (-not (Test-Path 'runners')) { New-Item -ItemType Directory -Path 'runners' | Out-Null }
$b64 = ''
$bytes = [System.Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes((Join-Path $PWD 'runners\run-states.ps1'), $bytes)
Write-Host 'Written: runners/run-states.ps1' -ForegroundColor Green

git add runners/run-states.ps1
git commit -m "Fix: delete per-state iteration files from previous run before launching new run"
git push origin main

if ($LASTEXITCODE -eq 0) {
    Write-Host ''
    Write-Host 'Done! Each new run now clears stale state files first.' -ForegroundColor Green
} else {
    Write-Host 'Push failed' -ForegroundColor Red
}
